Q: How can I run both php and html code from MySQL? A: <p>You would have to do a <strong>SELECT * FROM tbl_name</strong>, they put everything into a <strong>$mysql_fetch_assoc()</strong> function.</p>

<p>Something like this: </p>

<pre><code>$result = mysql_query("SELECT * FROM website");
$row = mysql_fetch_assoc($result);
$row['page_title'];
$row['page_content'];
</code></pre>

Q: Issue a new claim from ChallengeResult() in IdentityServer4 A: <p>Since I host some API-functions in the Identity Server to do some internal user modifications I needed tenant to be reflected in the token so that the calls to this API could be validated.</p>

<p>I managed it by implementing a new custom grant in the Identity Server which looks at the raw context and pulls out the requested tenant.</p>

<pre><code> public class ActAsGrantValidator : IExtensionGrantValidator
    {
        private readonly ITokenValidator _tokenValidator;
        private readonly ITenantStore _tenantStore;
        public ActAsGrantValidator(ITokenValidator tokenValidator, ITenantStore tenantStore)
        {
            _tokenValidator = tokenValidator;
            _tenantStore = tenantStore;
        }
        public string GrantType =&gt; "act-as";

        public async Task ValidateAsync(ExtensionGrantValidationContext context)
        {
            var userToken = context.Request.Raw.Get("accessToken");
            var tenant = context.Request.Raw.Get("chosenTenant");

            if (string.IsNullOrEmpty(userToken))
            {
                context.Result = new GrantValidationResult(TokenRequestErrors.InvalidGrant);
                return;
            }

            var result = await _tokenValidator.ValidateAccessTokenAsync(userToken);
            if (result.IsError)
            {
                context.Result = new GrantValidationResult(TokenRequestErrors.InvalidGrant);
                return;
            }
            // logic to validate the user and tenant
            // ..
            // issue a new claimsprincipal to reflect the new "persona"
            var claims = result.Claims.ToList();
            claims.RemoveAll(p =&gt; p.Type == "role");
            claims.RemoveAll(p =&gt; p.Type == "chosentenant");
            claims.Add(new Claim("chosentenant", tenant));
            var identity = new ClaimsIdentity(claims);
            var principal = new ClaimsPrincipal(identity);
            context.Result = new GrantValidationResult(principal);
            return;
       }
    }
</code></pre>

<p>Then in a controller from the API I call the custom grant:</p>

<pre><code>            // access token from httpcontext, chosenTenant from controller
            var payload = new
            {
                accessToken,
                chosenTenant
            };
            var tokenClient = new TokenClient($"{_identityServerSettings.Authority}/connect/token",
                _identityServerSettings.ClientId, _identityServerSettings.ClientSecret);
            var response = await tokenClient.RequestCustomGrantAsync("act-as", "profile openid", payload);
</code></pre>

<p>And then do a relogin with the claims from the new access token and calling the user info endpoint:</p>

<pre><code>            var authProperties = new AuthenticationProperties();
            authProperties.StoreTokens(tokens);
            authProperties.ExpiresUtc = DateTime.Now.AddHours(9);
            var identity = new ClaimsIdentity(claims, "Cookies");
            var principal = new ClaimsPrincipal(identity);
            await _httpContext.HttpContext.SignInAsync("Cookies", principal, authProperties);
</code></pre>
